import React, { useEffect, useRef, useState } from 'react';
import { MoraPackFlightSimulation } from '../../utils/flightSimulation';
import './Simulador.css';

const Simulador = () => {
  const mapRef = useRef(null);
  const simulationRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState(1);
  const [currentTime, setCurrentTime] = useState('');
  const [elapsedTime, setElapsedTime] = useState('00 : 00 : 00');
  const [currentView, setCurrentView] = useState('flights');

  useEffect(() => {
    // Cargar Leaflet CSS dinámicamente
    const leafletCSS = document.createElement('link');
    leafletCSS.rel = 'stylesheet';
    leafletCSS.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
    document.head.appendChild(leafletCSS);

    // Cargar Leaflet JS dinámicamente
    const leafletJS = document.createElement('script');
    leafletJS.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    leafletJS.onload = () => {
      // Inicializar simulación después de que Leaflet se cargue
      if (mapRef.current && !simulationRef.current) {
        simulationRef.current = new MoraPackFlightSimulation(mapRef.current);
        setIsPlaying(true);
      }
    };
    document.head.appendChild(leafletJS);

    // Actualizar tiempo cada segundo
    const timeInterval = setInterval(() => {
      if (simulationRef.current) {
        setCurrentTime(simulationRef.current.getCurrentTime());
        setElapsedTime(simulationRef.current.getElapsedTime());
      }
    }, 1000);

    return () => {
      clearInterval(timeInterval);
      // Limpiar scripts al desmontar
      document.head.removeChild(leafletCSS);
      document.head.removeChild(leafletJS);
    };
  }, []);

  const handlePlay = () => {
    if (simulationRef.current) {
      simulationRef.current.play();
      setIsPlaying(true);
    }
  };

  const handlePause = () => {
    if (simulationRef.current) {
      simulationRef.current.pause();
      setIsPlaying(false);
    }
  };

  const handleStop = () => {
    if (simulationRef.current) {
      simulationRef.current.stop();
      setIsPlaying(false);
    }
  };

  const handleSpeedChange = () => {
    const speeds = [1, 2, 4, 8];
    const currentIndex = speeds.indexOf(speed);
    const nextSpeed = speeds[(currentIndex + 1) % speeds.length];
    setSpeed(nextSpeed);
    if (simulationRef.current) {
      simulationRef.current.setSpeed(nextSpeed);
    }
  };

  const handleRestart = () => {
    if (simulationRef.current) {
      simulationRef.current.stop();
      setTimeout(() => {
        simulationRef.current.startSimulation();
        setIsPlaying(true);
      }, 100);
    }
  };

  const handleViewChange = (view) => {
    setCurrentView(view);
    // Aquí se puede implementar la lógica para cambiar la vista del mapa
  };

  return (
    <div className="simulador-container">
      {/* Sidebar */}
      <div className="simulation-sidebar">
        <div className="sidebar-header">
          <h3><i className="fas fa-cogs"></i> Modos de Operación</h3>
        </div>
        <div className="sidebar-menu">
          <button className="sidebar-item active">
            <i className="fas fa-broadcast-tower"></i>
            <span>Monitoreo en Tiempo Real</span>
          </button>
          <button className="sidebar-item disabled" disabled>
            <i className="fas fa-calendar-week"></i>
            <span>Simulación Semanal</span>
            <small>Próximamente</small>
          </button>
          <button className="sidebar-item disabled" disabled>
            <i className="fas fa-exclamation-triangle"></i>
            <span>Simulación de Colapso</span>
            <small>Próximamente</small>
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="simulation-main-content">
        <div className="control-panel">
          <h2>Monitoreo en Tiempo Real</h2>
          <div className="status-section">
            <span className="status-label">Estado de la Simulación:</span>
            <span className="status-text">
              {isPlaying ? 'Monitoreo en tiempo real activo' : 'Simulación pausada'}
            </span>
          </div>

          {/* Simulation Controls */}
          <div className="simulation-controls">
            <h3><i className="fas fa-cogs"></i> Simulación</h3>
            <div className="control-buttons">
              <button 
                className="sim-control-btn play-btn" 
                onClick={handlePlay}
                disabled={isPlaying}
              >
                <i className="fas fa-play"></i> Iniciar
              </button>
              <button 
                className="sim-control-btn pause-btn" 
                onClick={handlePause}
                disabled={!isPlaying}
              >
                <i className="fas fa-pause"></i> Pausar
              </button>
              <button 
                className="sim-control-btn stop-btn" 
                onClick={handleStop}
              >
                <i className="fas fa-stop"></i> Detener
              </button>
              <button 
                className="sim-control-btn speed-btn" 
                onClick={handleSpeedChange}
              >
                <i className="fas fa-tachometer-alt"></i> {speed}x
              </button>
              <button 
                className="sim-control-btn restart-btn" 
                onClick={handleRestart}
              >
                <i className="fas fa-redo-alt"></i> Reiniciar Todo
              </button>
            </div>
          </div>
        </div>

        {/* Map Container */}
        <div className="map-container">
          <div className="map-area">
            <div ref={mapRef} className="flight-map"></div>

            {/* Map Controls */}
            <div className="map-controls-bottom">
              <button 
                className={`map-btn vuelos-btn ${currentView === 'flights' ? 'active' : ''}`}
                onClick={() => handleViewChange('flights')}
              >
                <i className="fas fa-plane"></i>
                Vuelos
              </button>
              <button 
                className={`map-btn rutas-btn ${currentView === 'routes' ? 'active' : ''}`}
                onClick={() => handleViewChange('routes')}
              >
                <i className="fas fa-route"></i>
                Rutas
              </button>
              <button 
                className={`map-btn aeropuertos-btn ${currentView === 'airports' ? 'active' : ''}`}
                onClick={() => handleViewChange('airports')}
              >
                <i className="fas fa-map-marker-alt"></i>
                Aeropuertos
              </button>
            </div>
          </div>

          {/* Info Panel */}
          <div className="info-panel">
            <div className="info-header">
              <h3>Información del Sistema</h3>
            </div>

            <div className="time-section">
              <div className="current-time">
                <label>Hora actual:</label>
                <div className="time-display">{currentTime}</div>
              </div>

              <div className="elapsed-time">
                <label>Tiempo transcurrido:</label>
                <div className="time-counter">{elapsedTime}</div>
              </div>
            </div>

            <div className="stats-section">
              <div className="stat-item">
                <span className="stat-label">Vuelos Activos:</span>
                <span className="stat-value">12</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">Paquetes en Tránsito:</span>
                <span className="stat-value">2,847</span>
              </div>
              <div className="stat-item">
                <span className="stat-label">Aeropuertos Operativos:</span>
                <span className="stat-value">24</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Simulador;
